select is((select audience_count from public.publish_announcement((select id from boundary_ids where t=1 and k='promo'))),0,'ANC boundary: tenant 1 promo publish uses same inclusive-date audience');
select is((select audience_count from public.list_announcements() where announcement_id=(select id from boundary_ids where t=1 and k='live')),3,'ANC boundary: tenant 1 live staff list matches audience');
select is((public.read_announcement((select id from boundary_ids where t=1 and k='live'))->'announcement'->>'audienceCount')::integer,3,'ANC boundary: tenant 1 live staff detail matches audience');
select is((select audience_count from public.list_announcements() where announcement_id=(select id from boundary_ids where t=1 and k='not_live')),8,'ANC boundary: tenant 1 not_live staff list matches audience');
select is((public.read_announcement((select id from boundary_ids where t=1 and k='not_live'))->'announcement'->>'audienceCount')::integer,8,'ANC boundary: tenant 1 not_live staff detail matches audience');
select is((select audience_count from public.list_announcements() where announcement_id=(select id from boundary_ids where t=1 and k='all')),11,'ANC boundary: tenant 1 all staff list matches audience');
select is((public.read_announcement((select id from boundary_ids where t=1 and k='all'))->'announcement'->>'audienceCount')::integer,11,'ANC boundary: tenant 1 all staff detail matches audience');
select is((select audience_count from public.list_announcements() where announcement_id=(select id from boundary_ids where t=1 and k='promo')),0,'ANC boundary: tenant 1 promo staff list matches audience');
select is((public.read_announcement((select id from boundary_ids where t=1 and k='promo'))->'announcement'->>'audienceCount')::integer,0,'ANC boundary: tenant 1 promo staff detail matches audience');
