set local role postgres;
select set_config('request.jwt.claims','',true);
-- Missing marketing consent withheld promotional exposure above; a latest grant
-- now admits the live endpoint member without changing membership or service consent.
insert into public.consents(id,tenant_id,member_id,purpose,granted,version,source,recorded_at) values(pg_temp.u(401),pg_temp.u(1),pg_temp.u(101),'marketing',true,'v1','signup',statement_timestamp());
select pg_temp.claim('member',null,101,1001,1);
set local role authenticated;
select is((select count(*)::integer from public.read_member_announcements() where announcement_id=(select id from boundary_ids where t=1 and k='promo')),1,'ANC boundary: granted marketing preserves live promotional exposure');
select ok(public.mark_announcement_read((select id from boundary_ids where t=1 and k='promo'),1),'ANC boundary: granted marketing permits read marker');
set local role postgres;
select set_config('request.jwt.claims','',true);
insert into public.consents(id,tenant_id,member_id,purpose,granted,version,source,recorded_at) values(pg_temp.u(402),pg_temp.u(1),pg_temp.u(101),'marketing',false,'v2','signup',statement_timestamp()+interval '1 second');
select pg_temp.claim('member',null,101,1001,1);
set local role authenticated;
select is((select count(*)::integer from public.read_member_announcements() where announcement_id=(select id from boundary_ids where t=1 and k='promo')),0,'ANC boundary: latest withdrawal still removes live promotional exposure');
select ok(not public.mark_announcement_read((select id from boundary_ids where t=1 and k='promo'),1),'ANC boundary: withdrawal still refuses marker');
set local role postgres;
select pg_temp.claim('gym_owner',21,null,921,1);
set local role authenticated;
